import {RECEIVING_ROUTES} from './receiving-routes.mjs';
import {displayNetworkFee} from './network-fees.mjs';
import {mountDashboard,icon} from './dashboard.mjs';
import {currencyFields,CURRENCIES,historyHTML,renderHistory,escapeHTML as esc} from './transfer-ui.mjs';
import {createFundingService} from './funding-service.mjs';
import {fromUnits,toUnits,transferQuote,validateAddress,networkLabel,TOKEN_CONTRACTS} from './funding-catalog.mjs';
import qrcode from './vendor/qrcode-2.0.4.mjs';
export function depositQR(address,network){validateAddress(network,address);const qr=qrcode(0,'M');qr.addData(address);qr.make();return qr.createSvgTag({cellSize:5,margin:20,scalable:true});}
export function depositHTML({preview=false}={}){return '<div class="deposit-page"><div class="deposit-page-heading"><span class="deposit-heading-icon">'+icon('deposit')+'</span><div><h1>Deposit Crypto</h1><p>Deposit cryptocurrency to fund your account</p></div></div><div class="deposit-columns"><section class="deposit-panel new-deposit"><h2 id="new-deposit-title">'+icon('wallet')+' New Deposit</h2><div class="deposit-current-balance"><span>Available Balance</span><strong id="deposit-balance">Sign in to view balance</strong></div><ol class="deposit-steps" aria-label="Deposit progress"><li class="current"><span>1</span></li><li><span>2</span></li><li><span>3</span></li></ol><div id="deposit-step-content"></div><p id="funding-error" class="deposit-error" role="alert" hidden></p><p class="deposit-availability">'+''+'Only configured receiving networks can accept deposits. Account credit requires manual verification.</p></section>'+historyHTML('deposit')+'</div></div>';}
export function mountDeposit(root,options={}){
 mountDashboard(root,{...options,view:'deposit',mainHTML:depositHTML(options)});
 const slot=root.querySelector('#deposit-step-content'),error=root.querySelector('#funding-error');let asset='BTC',network='bitcoin',amount='',data={routes:options.preview?RECEIVING_ROUTES:[],balances:[],history:[]},service=null,requestId=crypto.randomUUID(),busy=false;
 function fail(e){error.textContent=e.message||String(e);error.hidden=false;}
 function clear(){error.hidden=true;}
 function progress(n){root.querySelectorAll('.deposit-steps li').forEach((li,i)=>{li.classList.toggle('current',i===n-1);li.classList.toggle('complete',i<n-1);if(i===n-1)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});}
 function balance(){root.querySelector('#deposit-balance').textContent=service?(data.balances.find(b=>b.asset===asset)?.available||'0')+' '+asset:'Sign in to view balance';}
 function history(){renderHistory(root.querySelector('#funding-history'),data.history.filter(r=>r.kind==='deposit'),{open:payment});}
 async function refresh(){if(!service)return;data=await service.load();balance();history();}
 function choose(){clear();progress(1);root.querySelector('#new-deposit-title').innerHTML=icon('wallet')+' New Deposit';slot.innerHTML='<div class="deposit-step-heading"><h3>Select Currency & Network</h3><p>Choose the asset and the network you will send from.</p></div><form id="deposit-network-form">'+currencyFields('deposit',asset,network,data.routes)+'<p id="deposit-route-note" class="transfer-caption" role="status"></p><button class="deposit-continue" type="submit">Continue '+icon('arrow')+'</button></form>';balance();const note=slot.querySelector('#deposit-route-note');const route=data.routes.find(r=>r.asset===asset&&r.network===network);note.textContent=route?.enabled?'Receiving address configured. Confirm the network before continuing.':(route?.address?'Unavailable · receiving address saved; awaiting deposit activation.':'Unavailable · no valid receiving address configured.');slot.querySelector('#deposit-currency').onchange=e=>{asset=e.target.value;network=CURRENCIES[asset].networks[0];amount='';choose();};slot.querySelector('#deposit-network').onchange=e=>{network=e.target.value;choose();};slot.querySelector('form').onsubmit=e=>{e.preventDefault();enterAmount();};}
 function enterAmount(){clear();progress(2);slot.innerHTML='<div class="deposit-step-heading"><h3>Enter Amount</h3><p>'+asset+' · '+networkLabel(asset,network)+'</p></div><form id="deposit-form"><div class="transfer-field"><label for="deposit-amount">Amount ('+asset+')</label><input id="deposit-amount" inputmode="decimal" autocomplete="off" placeholder="0.00" value="'+esc(amount)+'" required></div><dl class="withdraw-summary"><div><dt>Aurex deposit charge</dt><dd id="deposit-fee"></dd></div><div><dt>Sending network fee</dt><dd>Quoted by your wallet</dd></div><div><dt>Account credit after review</dt><dd id="deposit-net">—</dd></div></dl><p class="transfer-caption">The amount is in '+asset+', not USD. Your wallet may charge an additional network fee.</p><div class="transfer-actions"><button type="button" id="deposit-back" class="transfer-back">← Back</button><button type="submit" id="generate-deposit" class="deposit-continue">Generate Payment '+icon('arrow')+'</button></div><p id="deposit-disabled-note" class="transfer-caption"></p></form>';const route=data.routes.find(r=>r.asset===asset&&r.network===network);const feeInfo=document.createElement('p');feeInfo.className='transfer-caption network-fee-info';slot.querySelector('.withdraw-summary').after(feeInfo);displayNetworkFee(feeInfo,asset,network);slot.querySelector('#deposit-fee').textContent=route?.enabled?route.deposit_fee+' '+asset:'Not configured';const submit=slot.querySelector('#generate-deposit');submit.disabled=!service||!route?.enabled;slot.querySelector('#deposit-disabled-note').textContent=submit.disabled?'Payment generation becomes available after sign-in and receiving-address configuration.':'';slot.querySelector('#deposit-amount').oninput=e=>{amount=e.target.value;try{slot.querySelector('#deposit-net').textContent=transferQuote(amount,route?.deposit_fee||'0',asset).receive+' '+asset;}catch{slot.querySelector('#deposit-net').textContent='—';}};slot.querySelector('#deposit-back').onclick=choose;slot.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;clear();busy=true;submit.disabled=true;try{if(!service||!route?.enabled)throw Error('This network is not configured for deposits.');amount=fromUnits(toUnits(slot.querySelector('#deposit-amount').value,asset),asset);transferQuote(amount,route.deposit_fee,asset);validateAddress(network,route.address);const row=await service.create('deposit',asset,network,amount,requestId);await refresh();payment(row);}catch(e){fail(e);submit.disabled=false;}finally{busy=false;}};}
 function payment(row){clear();asset=row.asset;network=row.network;amount=row.amount;balance();progress(3);root.querySelector('#new-deposit-title').innerHTML=icon('wallet')+' Complete Payment';let svg='';try{svg=depositQR(row.address,network);}catch(e){fail(Error('The receiving address needs operator verification. Do not send funds.'));return;}slot.innerHTML='<div class="deposit-step-heading"><h3>Complete Payment</h3><p>Send crypto to the address below</p></div><div class="payment-state" role="status">'+esc(row.status.replaceAll('_',' '))+'</div><div class="payment-qr" aria-label="Receiving address QR code">'+svg+'</div><p class="payment-label">Send Amount</p><div class="payment-copy"><strong>'+esc(row.amount)+' '+asset+'</strong><button type="button" id="copy-payment-amount" aria-label="Copy payment amount">'+'<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M15 8V4H4v11h4"/></svg>'+'</button></div><p class="transfer-caption">Send the amount shown. The credited amount is verified manually.</p><p class="payment-label">To This Address</p><div class="payment-address"><code>'+esc(row.address)+'</code><button type="button" id="copy-payment-address" aria-label="Copy receiving address">Copy</button></div>'+(row.memo?'<div class="payment-important"><strong>Required memo / destination tag</strong><p>'+esc(row.memo)+'</p><small>Enter this separately in your wallet. The QR contains the address only.</small></div>':'')+'<dl class="withdraw-summary"><div><dt>Aurex deposit charge</dt><dd>'+esc(row.fee)+' '+asset+'</dd></div><div><dt>Sending network fee</dt><dd>Quoted by your wallet</dd></div><div><dt>Account credit after review</dt><dd>'+transferQuote(row.amount,row.fee,asset).receive+' '+asset+'</dd></div></dl><div class="payment-important"><strong>ⓘ Important</strong><p>Send only '+asset+' on '+networkLabel(asset,network)+'. Sending another asset or using another network may result in permanent loss.</p><p>This receiving address has no automatic expiry. Reporting a transaction does not credit your account until it is verified.</p></div>'+(row.status==='awaiting_payment'?'<form id="report-payment"><div class="transfer-field"><label for="payment-hash">Transaction hash / signature</label><input id="payment-hash" autocomplete="off" required maxlength="100" placeholder="Paste the hash from your sending wallet"></div><details><summary>Multiple transfers in the same transaction?</summary><div class="transfer-field"><label for="payment-index">Transfer index (default 0)</label><input id="payment-index" type="number" min="0" step="1" value="0"></div></details><button class="deposit-continue" type="submit">Submit for Verification</button></form>':'<p class="transfer-caption">'+esc(row.status==='pending_review'?'Transaction submitted. Awaiting manual review.':row.review_note||'')+'</p>')+'<div class="transfer-actions"><button id="new-deposit" class="transfer-back" type="button">+ New Deposit</button><button id="check-deposit" class="transfer-back" type="button">↻ Check Status</button><button id="download-qr" class="transfer-back" type="button">Download QR</button></div><p id="payment-feedback" role="status" class="transfer-caption"></p>';
 const feeInfo=document.createElement('p');feeInfo.className='transfer-caption network-fee-info';slot.querySelector('.withdraw-summary').after(feeInfo);displayNetworkFee(feeInfo,asset,network);const token=TOKEN_CONTRACTS[asset]?.[network];if(token){const info=document.createElement('p');info.className='transfer-caption token-contract';info.textContent=token.label+' · Token contract: '+token.address+'. This is the token contract, not the receiving address.';slot.querySelector('.payment-address').after(info);}
 async function copy(text){try{await navigator.clipboard.writeText(text);slot.querySelector('#payment-feedback').textContent='Copied';}catch{slot.querySelector('#payment-feedback').textContent='Select and copy the value manually.';}}
 slot.querySelector('#copy-payment-address').onclick=()=>copy(row.address);slot.querySelector('#copy-payment-amount').onclick=()=>copy(row.amount);slot.querySelector('#new-deposit').onclick=()=>{requestId=crypto.randomUUID();choose();};slot.querySelector('#check-deposit').onclick=async e=>{e.target.disabled=true;try{await refresh();payment(data.history.find(r=>r.id===row.id)||row);}catch(e){fail(e);}};slot.querySelector('#download-qr').onclick=()=>{const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download='aurex-'+asset+'-'+network+'-qr.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};const form=slot.querySelector('#report-payment');if(form)form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;form.querySelector('button').disabled=true;try{const updated=await service.report(row,slot.querySelector('#payment-hash').value,Number(slot.querySelector('#payment-index').value));await refresh();payment(updated);}catch(e){fail(e);form.querySelector('button').disabled=false;}finally{busy=false;}};
 }
 choose();if(options.preview&&options.paymentExample)payment(options.paymentExample);if(!options.preview)Promise.resolve(options.getAccounts?.()).then(async accounts=>{if(!accounts)return;service=createFundingService(accounts);await refresh();if(root.contains(slot)&&slot.querySelector('#deposit-network-form'))choose();else if(root.contains(slot)&&slot.querySelector('#deposit-form'))enterAmount();}).catch(fail);window.scrollTo(0,0);
}
